import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.BxCN1dRw.js";const p=JSON.parse('{"title":"Walkthrough: Load, saturation and soak reports","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/load-reports"},"headers":[],"relativePath":"en/tutorials/load-reports.md","filePath":"en/tutorials/load-reports.md"}'),s={name:"en/tutorials/load-reports.md"};function n(d,e,i,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="walkthrough-load-saturation-and-soak-reports" tabindex="-1">Walkthrough: Load, saturation and soak reports <a class="header-anchor" href="#walkthrough-load-saturation-and-soak-reports" aria-label="Permalink to &quot;Walkthrough: Load, saturation and soak reports&quot;">​</a></h1><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/CONTEXT.md" target="_blank" rel="noreferrer">performance contract</a> of the <a href="./perf-gates">previous chapter</a> governs deterministic budgets: round-trips, rows, bytes — verified by every CI run. This chapter adds the other half of <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/docs/saas-template-architecture-spec.md" target="_blank" rel="noreferrer">spec §17.3</a> — wall-clock behavior: what ordinary load looks like, where the saturation point appears under concurrency, and whether the queue and memory stay stable over a long run. Such numbers jitter across machines by nature, so the template sets three rules for them: <strong>load only ever hits a controlled stack, never your existing database</strong>; <strong>reports are produced on nightly runs and version releases, never inside an ordinary PR gate</strong>; <strong>throttling is not an error</strong> — <code>429</code> with <code>rate_limit.exceeded</code> is a documented backpressure contract, reported as a separate &quot;expected throttles&quot; category, presented apart from real business errors.</p><h2 id="_1-the-controlled-load-stack-stress-the-temporary-stack-not-your-data" tabindex="-1">1. The controlled load stack: stress the temporary stack, not your data <a class="header-anchor" href="#_1-the-controlled-load-stack-stress-the-temporary-stack-not-your-data" aria-label="Permalink to &quot;1. The controlled load stack: stress the temporary stack, not your data&quot;">​</a></h2><p>Every load command first brings up a fresh <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/CONTEXT.md" target="_blank" rel="noreferrer">controlled load stack</a> via <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/scripts/perf/stack.mjs" target="_blank" rel="noreferrer">stack.mjs</a>: the repository&#39;s own development compose file, but started under the isolated project name <code>saas-perf</code>, with every service assigned a free port on the spot and volumes isolated per project — your development stack (project <code>axum-saas-template</code>) and any production deployment cannot be touched, not even sharing a data directory. The API and Worker run as release builds from the host, because capacity readings should measure the product itself. When the command ends (success or failure) it runs <code>down -v</code>, destroying the stack with its volumes; the stack never exists in a &quot;finished run, data left behind&quot; state. For post-mortems, <code>PERF_STACK_KEEP=1</code> keeps it and the script prints the destroy command.</p><p>Rate limiting on the stack is relaxed to a million requests per minute — a capacity reading should measure the application, not the local defaults (20 registrations per minute would drown the seeding loop). The local fallback quota used when Redis degrades is relaxed too: under load the Redis counter occasionally misses the budget and the limiter falls back to the local per-peer bucket; with the default 120/minute fallback the whole window would become a 429 storm instead of a capacity reading. The scenario code still classifies and counts 429s per request, so if you ever restore real limits and rerun, the report stays honest.</p><h2 id="_2-data-and-scenarios-everything-through-public-interfaces" tabindex="-1">2. Data and scenarios: everything through public interfaces <a class="header-anchor" href="#_2-data-and-scenarios-everything-through-public-interfaces" aria-label="Permalink to &quot;2. Data and scenarios: everything through public interfaces&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/scripts/perf/fixtures.mjs" target="_blank" rel="noreferrer">fixtures.mjs</a> seeds the dataset at a configurable scale entirely through the public HTTP interfaces — registration, document creation, attachment upload — never writing the database directly. The scale tier and the actual seeded counts go into the report&#39;s fixtures metadata, so every number can be traced to &quot;measured on this much data&quot;.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>File</th><th>What it does</th><th>Default tier</th></tr></thead><tbody><tr><td><code>load</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/scripts/perf/k6/load.js" target="_blank" rel="noreferrer">k6/load.js</a></td><td>Ordinary load: a signed-in read-heavy mix (list / read document / occasional create), constant concurrency</td><td>4 VU × 60s</td></tr><tr><td><code>saturation</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/scripts/perf/k6/saturation.js" target="_blank" rel="noreferrer">k6/saturation.js</a></td><td>A read-only mix driven up a fixed concurrency ladder by the runner, merged into a throughput-concurrency curve</td><td>1→32 VU × 20s</td></tr><tr><td><code>trajectory</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/scripts/perf/k6/trajectory.js" target="_blank" rel="noreferrer">k6/trajectory.js</a></td><td>A real user journey: register → sign in → create → edit conflict (retry after 409) → attachment upload/download → export request → wait for the Worker → download export → notification</td><td>2 VU × 60s</td></tr><tr><td><code>soak</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/scripts/perf/k6/soak.js" target="_blank" rel="noreferrer">k6/soak.js</a></td><td>A low-concurrency long run: edit, attachment and export-request loops, watching queue drain and memory trends</td><td>2 VU × 600s</td></tr></tbody></table><p>Each VU signs in once on its first iteration and reuses the session; write requests carry random idempotency keys and are indistinguishable from any other client. When k6 is missing, the commands print install instructions and exit — they never pretend to have run; reports in the repository are produced with k6 v2.3.0.</p><h2 id="_3-what-the-report-contains-and-how-to-read-it" tabindex="-1">3. What the report contains and how to read it <a class="header-anchor" href="#_3-what-the-report-contains-and-how-to-read-it" aria-label="Permalink to &quot;3. What the report contains and how to read it&quot;">​</a></h2><p>Every command writes <code>.scratch/perf/&lt;scenario&gt;-report.json</code> with four blocks:</p><ul><li><strong>k6 metrics</strong>: throughput (req/s), P50/P95/P99 of <code>http_req_duration</code>, check failure rate, and the <code>expected_throttles</code> and <code>business_errors</code> counters — business errors split further into <code>business_error_4xx</code> / <code>business_error_5xx</code> columns: a 4xx wave is a regression, a 5xx wave is capacity degradation, tellable at a glance. Read steady-state reports business-errors-first — a run with business errors flooding the counters is not a reading, it is an incident record.</li><li><strong>Reading the saturation point</strong> (saturation report): throughput rises with concurrency until a tier where it stops growing and errors start appearing — the turning point of the curve is the saturation point. The report offers a <code>plateauFromVUs</code> hint (the smallest concurrency tier reaching 90% of the best tier&#39;s throughput); it is a reading aid and asserts nothing. Steady-state scenarios (load / trajectory / soak) carry the <code>business_errors</code> guard track that keeps error-flooding runs out of the readings; the saturation ladder deliberately crosses capacity, and errors at the top tiers are exactly the signal to observe — so it has no such track: errors are recorded as 4xx/5xx in the report instead of failing the command.</li><li><strong>Stack samples</strong>: taken every 2 seconds during the scenario — connection pool usage (<code>pg_stat_activity</code>), job queue depth (grouped by <code>saas_core.jobs</code> state), and api/worker process RSS — aggregated into min/avg/max, with the raw sample series kept. The soak&#39;s value lives on this timeline.</li><li><strong>Environment metadata</strong>: scale tier, VU count, duration, rate-limit configuration, fixtures facts — a report must carry its own reproduction conditions.</li></ul><h2 id="_4-where-to-run-it-and-how-to-tune-it" tabindex="-1">4. Where to run it and how to tune it <a class="header-anchor" href="#_4-where-to-run-it-and-how-to-tune-it" aria-label="Permalink to &quot;4. Where to run it and how to tune it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-load</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Or perf-saturation / perf-trajectory / perf-soak</span></span></code></pre></div><p>The only prerequisite is k6. Scale and duration are all adjusted through environment variables; the commands take no arguments:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PERF_SCALE</code></td><td><code>sm</code></td><td>Data scale tier (sm / md / lg)</td></tr><tr><td><code>PERF_USERS</code> / <code>PERF_DOCS_PER_USER</code></td><td>Set by tier</td><td>Precise override of seeded counts</td></tr><tr><td><code>PERF_VUS</code></td><td>Set by scenario</td><td>Number of concurrent virtual users</td></tr><tr><td><code>PERF_DURATION</code></td><td>Set by scenario</td><td>Duration in seconds (saturation uses <code>PERF_STEP_SECS</code>)</td></tr><tr><td><code>PERF_STEPS</code></td><td><code>1,4,8,16,32</code></td><td>Concurrency tiers of the saturation ladder</td></tr><tr><td><code>PERF_STEP_SECS</code></td><td><code>20</code></td><td>Seconds per saturation tier</td></tr><tr><td><code>PERF_SAMPLE_MS</code></td><td><code>2000</code></td><td>Stack sampling interval (pool / queue / RSS, milliseconds)</td></tr><tr><td><code>PERF_STACK_KEEP</code></td><td>Unset</td><td>Set to <code>1</code> to keep the stack for investigation</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/.github/workflows/perf-nightly.yml" target="_blank" rel="noreferrer">perf-nightly.yml</a> runs the full set nightly (and on manual trigger): installs k6 with checksum verification, runs load / the saturation ladder (shortened) / trajectory / a time-boxed soak, and keeps the reports as artifacts for 30 days. Ordinary PRs never run them — on PRs there is only the <a href="./perf-gates">previous chapter&#39;s deterministic gate</a>.</p><h2 id="_5-the-first-measurements-and-where-things-go-after-example-removal" tabindex="-1">5. The first measurements and where things go after example removal <a class="header-anchor" href="#_5-the-first-measurements-and-where-things-go-after-example-removal" aria-label="Permalink to &quot;5. The first measurements and where things go after example removal&quot;">​</a></h2><p>The first measurements are archived below (local x86_64 WSL2, default tier of 6 users × 8 documents; the numbers drift with machine, neighbor load and data distribution — the archive gives later readers a comparable starting point, not a promise on any machine):</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Config (default tier)</th><th>Throughput</th><th>P50 / P95 / P99</th><th>Business errors</th></tr></thead><tbody><tr><td>load</td><td>4 VU × 60s</td><td>308.1 req/s (18,480 requests)</td><td>10.5 / 28.3 / 38.1 ms</td><td>0</td></tr><tr><td>saturation</td><td>1→16 VU × 15s</td><td>131.9 → 270.9 → 270.2 → 177.4 req/s</td><td>p95: 10.3 → 23.5 → 54.8 → 155.2 ms</td><td>23 and 29 at the 8 and 16 VU tiers, all 5xx</td></tr><tr><td>trajectory</td><td>2 VU × 60s</td><td>46.3 req/s (164 complete journeys)</td><td>p95 34.8 ms</td><td>0</td></tr><tr><td>soak</td><td>2 VU × 300s</td><td>9.4 req/s (2,832 requests)</td><td>20.5 / — / 24.0 ms</td><td>0</td></tr></tbody></table><p>Reading per §3: the saturation curve enters 90%+ of the best throughput (270.9 req/s) at the 4 VU tier, <code>plateauFromVUs=4</code>; pushing concurrency further drops throughput and stretches p95 nearly sixfold, with 5xx appearing at the 8/16 VU tiers — exactly the capacity-degradation signal this curve exists to observe, recorded as-is without a fail verdict. The soak&#39;s 151 samples are where the long-run value is: api process RSS stayed at 61.9–62.5 MiB throughout and worker at 17.0–17.3 MiB, pool usage stable at 3–7, the export queue peaked at 2 and drained instantly — five minutes show no sign of a leak or backlog. k6 v2.3.0; the full reports (raw sample series and environment metadata included) are written by the commands to <code>.scratch/perf/*-report.json</code> and never committed.</p><p>The example-removal boundary is the same line as the <a href="./perf-gates">performance gates</a>: the four scenarios and fixtures ride on the knowledge-base example&#39;s endpoints, and after example removal <code>just perf-load</code> and friends explain honestly and exit before starting work. The scenario scripts and fixtures stay in the repository as skeleton templates, but what is genuinely business-agnostic and keeps working after removal are the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/scripts/perf/stack.mjs" target="_blank" rel="noreferrer">controlled load stack</a>, the sampler and the report structure (<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/scripts/perf/report.mjs" target="_blank" rel="noreferrer">report.mjs</a>). When modeling your own business: swap the scenarios for your hot-path endpoints and the fixtures for your domain data, and keep the &quot;throttles listed separately, saturation only recorded&quot; rules exactly as they are.</p><p>One written decision about microbenchmarks: this ticket evaluated attaching Criterion to the export rendering (the workspace&#39;s only pure-compute hotspot). It is not on the hot path — exports are asynchronous jobs — while Criterion would enter the compile cost of every <code>clippy --all-targets</code>. The conclusion was not to introduce it; the load evidence the spec asks for comes from the scenario reports, and should a genuine hot-path pure function appear, the same section&#39;s process covers adding one.</p><h2 id="_6-run-this-chapter-s-checks" tabindex="-1">6. Run this chapter&#39;s checks <a class="header-anchor" href="#_6-run-this-chapter-s-checks" aria-label="Permalink to &quot;6. Run this chapter&#39;s checks&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-load</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Any load command completing verifies this chapter&#39;s chain</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # The main gate contains no load scenarios — by design</span></span></code></pre></div><p>The post-removal behavior is accepted by the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/tests/tooling/example-remove.test.mjs" target="_blank" rel="noreferrer">removal tooling tests</a> and the removal CI; the load commands&#39; honest exit follows the same pattern as <code>production-smoke</code>.</p><hr><p>Source version：<code>0d2db282c3de</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/docs/tutorials/25-load-reports.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,28)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
